/* Der Kurs des Reiches: drei Achsen (-100..100), die jede Entscheidung verschiebt
   und die Runde für Runde passiv auf das ganze Spiel wirken. */
function nudge(s,o){if(!s.course)s.course={crown:0,coin:0,commons:0};for(const k in o)s.course[k]=clamp((s.course[k]||0)+o[k],-100,100)}
function courseEffects(s){const c=s.course||{crown:0,coin:0,commons:0};
 s.stats.legitimacy+=c.crown/45;s.factions.nobles-=c.crown/60;s.factions.cities-=c.crown/75;
 s.stats.trade+=c.coin/60;s.inflation=clamp(s.inflation+c.coin/1400,0,20);s.factions.merchants+=c.coin/70;
 s.factions.people+=c.commons/50;s.factions.nobles-=c.commons/95;s.reserve-=Math.max(0,c.commons)*3500;for(const r of Object.values(s.regions))r.loyalty+=c.commons/140;
 let p=s.lifePaths||{};s.stats.army+=(p['war:press']||0)*.12;s.stats.stability-=(p['war:press']||0)*.08;s.stats.trade+=(p['economy:press']||0)*.12;s.factions.people-=(p['economy:press']||0)*.08;s.stats.stability+=(p['realm:compromise']||0)*.1;s.stats.legitimacy+=(p['realm:crown']||0)*.1;s.private.stress-=(p['private:family']||0)*.12;s.private.stress+=(p['private:duty']||0)*.1;
}
function topUnrest(s){return Object.entries(s.regions).sort((a,b)=>b[1].unrest-a[1].unrest)[0][0]}
function pickPetitions(){
 let eligible=PETITIONS.filter(p=>!p.when||p.when(state));
 const recent=(state.petitionHistory||[]).slice(-10);
 let pool=eligible.filter(p=>!recent.includes(p.id)&&p.id!==state.pendingScenario);
 if(pool.length<2)pool=eligible.filter(p=>p.id!==state.pendingScenario);if(pool.length<2)pool=eligible;
 let picks=[],idx=state.turn*5+state.year+state.decisions.length,avail=pool.slice();
 while(picks.length<2&&avail.length){let i=Math.abs(idx+picks.length*7)%avail.length;picks.push(avail.splice(i,1)[0])}
 state.petitionHistory=[...(state.petitionHistory||[]),...picks.map(p=>p.id)].slice(-24);
 return picks.map(p=>({id:p.id,done:false,outcome:null}));
}
function inferConsequenceKind(title,text){let s=(title+' '+text).toLowerCase();if(s.includes('krieg')||s.includes('angriff')||s.includes('feldzug'))return 'war';if(s.includes('handel')||s.includes('wirtschaft')||s.includes('zoll')||s.includes('abgabe'))return 'economy';if(s.includes('diplomatie')||s.includes('gesandt')||s.includes('bündnis')||s.includes('frieden'))return 'diplomacy';if(s.includes('privat')||s.includes('familie')||s.includes('königin')||s.includes('prinz'))return 'private';if(s.includes('armee')||s.includes('flotte')||s.includes('garnison')||s.includes('doktrin')||s.includes('aushebung'))return 'military';if(s.includes('bau')||s.includes('grundstein')||s.includes('region'))return 'development';return 'realm'}
function queueConsequence(source,text,meta={}){if(meta.skipFollowup)return;if(!state.consequenceQueue)state.consequenceQueue=[];if(!state.pendingConsequences)state.pendingConsequences=[];let kind=meta.kind||inferConsequenceKind(source,text),id=`c${state.turn}-${Date.now()}-${state.decisions.length}`,due=state.turn+1+((state.turn+state.decisions.length)%3);state.consequenceQueue.push({id,due,source,kind,target:meta.target||null,origin:text,memoryId:meta.memoryId||null});state.consequenceQueue=state.consequenceQueue.slice(-16)}
function activateConsequences(){if(!state.consequenceQueue)state.consequenceQueue=[];if(!state.pendingConsequences)state.pendingConsequences=[];let due=state.consequenceQueue.filter(c=>c.due<=state.turn),later=state.consequenceQueue.filter(c=>c.due>state.turn);state.consequenceQueue=later;for(const c of due.slice(0,2)){state.pendingConsequences.push(c);let memory=state.memories?.find(m=>m.id===c.memoryId),title=`Spätfolge: ${c.source}`,text='Eine frühere Entscheidung verlangt nun nach einem neuen königlichen Beschluss.';state.events.unshift({turn:state.turn,date:dateLabel(),title,text,kind:c.kind,target:c.target,causeId:addHistoryEcho(memory,title,text,c.kind)})}for(const c of due.slice(2))state.consequenceQueue.push({...c,due:state.turn+1})}
function consequenceOptions(c){let rel=c.target&&state.relations[c.target];if(c.kind==='war')return [{id:'press',label:'DEN KURS VERSCHÄRFEN',hint:'2 Mio. Militärfonds · Militär +2 · Offiziere +2',apply:s=>{s.militaryFund=Math.max(0,s.militaryFund-2000000);s.stats.army+=2;s.factions.officers+=2;s.private.stress+=3}},{id:'limit',label:'DEN KONFLIKT BEGRENZEN',hint:'Stabilität +2 · Offiziere −2 · Beziehung entspannt',apply:s=>{s.stats.stability+=2;s.factions.officers-=2;if(c.target in s.relations)s.relations[c.target]+=4}}];if(c.kind==='economy')return [{id:'press',label:'VORTEIL AUSBAUEN',hint:'Handel +2 · Händler +3 · Zielbeziehung −4',apply:s=>{s.stats.trade+=2;s.factions.merchants+=3;if(c.target in s.relations)s.relations[c.target]-=4}},{id:'balance',label:'VERLIERER AUSGLEICHEN',hint:'1 Mio. ₲ · Volk +3 · Stabilität +1',apply:s=>{s.reserve=Math.max(0,s.reserve-1000000);s.factions.people+=3;s.stats.stability+=1}}];if(c.kind==='diplomacy')return [{id:'deepen',label:'BINDUNG VERTIEFEN',hint:'0,8 Mio. ₲ · Beziehung +6 · Handel +1',apply:s=>{s.reserve=Math.max(0,s.reserve-800000);if(c.target in s.relations)s.relations[c.target]+=6;s.stats.trade+=1}},{id:'distance',label:'ABSTAND BEWAHREN',hint:'Legitimität +2 · Beziehung −2 · keine Kosten',apply:s=>{s.stats.legitimacy+=2;if(c.target in s.relations)s.relations[c.target]-=2}}];if(c.kind==='private')return [{id:'family',label:'DIE FAMILIE VORANSTELLEN',hint:'Belastung −6 · Familie + · Verwaltung −1',apply:s=>{s.private.stress-=6;s.private.queen+=2;s.private.heir+=2;s.stats.stability-=1}},{id:'duty',label:'DIE KRONE VORANSTELLEN',hint:'Legitimität +2 · Belastung +5',apply:s=>{s.stats.legitimacy+=2;s.private.stress+=5}}];if(c.kind==='military')return [{id:'professional',label:'PROFESSIONALISIEREN',hint:'1,2 Mio. ₲ · Moral +4 · Militär +1',apply:s=>{s.reserve=Math.max(0,s.reserve-1200000);s.armies[0].morale+=4;s.stats.army+=1}},{id:'civil',label:'ZIVILE KONTROLLE STÄRKEN',hint:'Stabilität +2 · Offiziere −3 · Volk +2',apply:s=>{s.stats.stability+=2;s.factions.officers-=3;s.factions.people+=2}}];if(c.kind==='development')return [{id:'expand',label:'WEITER AUSBAUEN',hint:'1 Mio. ₲ · Infrastruktur + · Händler +2',apply:s=>{s.reserve=Math.max(0,s.reserve-1000000);s.factions.merchants+=2;s.stats.trade+=1}},{id:'local',label:'LOKALE BEDÜRFNISSE ACHTEN',hint:'Volk +3 · Stabilität +1',apply:s=>{s.factions.people+=3;s.stats.stability+=1}}];return [{id:'crown',label:'KÖNIGLICH DURCHSETZEN',hint:'Legitimität +2 · Adel −2 · Krone gestärkt',apply:s=>{s.stats.legitimacy+=2;s.factions.nobles-=2;nudge(s,{crown:3})}},{id:'compromise',label:'EINEN AUSGLEICH SUCHEN',hint:'Stabilität +2 · Volk +2 · Autorität verteilt',apply:s=>{s.stats.stability+=2;s.factions.people+=2;nudge(s,{crown:-2,commons:2})}}]}
const CONSEQUENCE_FOLLOWUP={war:'Offiziere und der Feind haben daraus längst eigene Schlüsse gezogen — die Front verlangt, dass Ihr die Richtung bestätigt oder korrigiert.',economy:'Händler, Gilden und einfache Leute haben ihre Geschäfte bereits danach ausgerichtet. Jetzt zeigt sich, wer von der Entscheidung profitiert und wer zurückbleibt.',diplomacy:'Am fremden Hof hat man die Botschaft genau registriert und erwartet nun eine klare Fortsetzung, keine Ausflüchte.',private:'Die Familie hat die Folgen zuerst gespürt — was im Palast begann, ist längst auch am Hof bekannt geworden.',military:'In Kasernen und auf Schiffen hat sich die Nachricht verbreitet; Offiziere und Mannschaften warten auf die nächste Weisung.',development:'Handwerker, Anwohner und Verwalter haben sich auf die neue Lage eingestellt. Jetzt entscheidet sich, ob die Krone ihren Kurs hält.',realm:'Das Reich hat die Entscheidung längst verarbeitet — der Rat verlangt nun eine klare Fortsetzung.'};
function consequencePanel(){let c=state.pendingConsequences&&state.pendingConsequences[0];if(!c)return '';let opts=consequenceOptions(c),origin=c.origin?c.origin.trim():'',follow=CONSEQUENCE_FOLLOWUP[c.kind]||CONSEQUENCE_FOLLOWUP.realm;return `<section class="consequence"><div class="consequence-origin"><div class="eyebrow">SPÄTFOLGE EINER FRÜHEREN ENTSCHEIDUNG</div><h2>${c.source}</h2><p>${origin?origin+' ':''}${follow}</p></div><div class="consequence-choices">${opts.map(o=>`<button data-consequence="${c.id}:${o.id}"><b>${o.label}</b><span>${decisionIntent(o.label,`${c.source} ${origin}`)}</span></button>`).join('')}</div></section>`}
function chooseConsequence(code){let[id,choiceId]=code.split(':'),c=state.pendingConsequences&&state.pendingConsequences.find(x=>x.id===id);if(!c)return;let o=consequenceOptions(c).find(x=>x.id===choiceId);if(!o)return;let snap=snapAll();o.apply(state);if(!state.lifePaths)state.lifePaths={};let path=`${c.kind}:${choiceId}`;state.lifePaths[path]=(state.lifePaths[path]||0)+1;state.pendingConsequences=state.pendingConsequences.filter(x=>x.id!==id);normalizeState();recordDecision(`Folgeweg · ${o.label}`,`${c.source} führte zu einem neuen Kurs. Seine Wirkungen entfalten sich in den kommenden Runden.`,{skipFollowup:true});persist();flashDeltas(snap);toast('Ein neuer Weg',`${o.label} — diese Richtung prägt künftige Folgen.`);render()}
function choosePetition(code){let[id,choiceId]=code.split(':');let entry=(state.petitions||[]).find(e=>e.id===id&&!e.done);if(!entry)return;let p=PETITIONS.find(x=>x.id===id),choice=p&&p.choices.find(c=>c.id===choiceId);if(!choice)return;let snap=snapAll();choice.apply(state);normalizeState();entry.done=true;entry.outcome=choice.label;recordDecision(`${p.title} — ${choice.label}`,'Eine Entscheidung des laufenden Hoftags verändert Interessen, Erwartungen und den weiteren Kurs des Reiches.');persist();flashDeltas(snap);toast('Entscheidung getroffen',`${choice.label}. Der Kurs des Reiches verschiebt sich.`);render()}
function petitionPanel(){
 if(!state.petitions||!state.petitions.length)return '';
 let open=state.petitions.filter(e=>!e.done);
 let cards=state.petitions.map(e=>{let p=PETITIONS.find(x=>x.id===e.id);if(!p)return '';
  if(e.done)return `<div class="petition resolved"><div class="pet-head"><span class="eyebrow">${p.category}</span><h3>${p.title}</h3></div><div class="pet-outcome"><b>✓ ${e.outcome}</b><span>Entschieden — die Folgen wirken bereits im Reich.</span></div></div>`;
  return `<div class="petition"><div class="pet-head"><span class="eyebrow">${p.category}</span><h3>${p.title}</h3></div><p>${p.text}</p><div class="pet-choices">${p.choices.map(c=>`<button data-petition="${p.id}:${c.id}"><b>${c.label}</b><span>${c.intent||decisionIntent(c.label,`${p.title} ${p.text}`)}</span></button>`).join('')}</div></div>`}).join('');
 return `<section class="petitions"><div class="petitions-head"><div><div class="eyebrow">HOFTAG DER RUNDE · ${open.length} OFFEN</div><h2>Entscheidungen des Reiches</h2></div><span class="pet-note">Unbeantwortete Petitionen entscheidet der Hof selbst — nicht immer zu Eurem Vorteil.</span></div><div class="petition-grid">${cards}</div></section>`;
}
function courseAxis(label,ln,rn,v){let pos=v>=0,w=Math.abs(v)/2,left=pos?50:50+v/2;return `<div class="course-axis"><div class="lbls"><span class="${v<-8?'on':''}">${ln}</span><b>${label}</b><span class="${v>8?'on':''}">${rn}</span></div><div class="course-track"><div class="course-fill ${pos?'pos':'neg'}" style="left:${left}%;width:${w}%"></div></div></div>`}
function coursePanel(){let c=state.course||{crown:0,coin:0,commons:0};return panel('KURS DES REICHES','Prägt jede Runde',`<div class="course-panel">${courseAxis('AUTORITÄT','STÄNDE','KRONE',c.crown)}${courseAxis('WIRTSCHAFT','VORSICHT','HANDEL',c.coin)}${courseAxis('GESELLSCHAFT','ELITEN','VOLK',c.commons)}<p class="course-note">Jede Entscheidung verschiebt den Kurs — und der Kurs wirkt Runde für Runde auf Gold, Fraktionen und Loyalität im ganzen Reich.</p></div>`)}
