const ENDINGS={
 seakaiser:{title:'Der Seekaiser',subtitle:'Krone über allen Meeren',lead:'Unter Aeron IV. wurde Valdorias Flagge auf jeder bekannten See gefürchtet und geachtet. Häfen von Frostholm bis zu den fernsten Inseln zahlten Zoll an die Krone von Caerhaven.'},
 eroberer:{title:'Der Eroberer des Nordens',subtitle:'Ein Reich, geschmiedet im Feuer',lead:'Wo einst Nordhaven trotzte, wehte nun das Banner Valdorias. Aerons Feldzüge machten aus einem Inselreich eine Macht, die den ganzen Norden umspannte.'},
 tyrann:{title:'Der Eiserne Monarch',subtitle:'Gefürchtet auf einem absoluten Thron',lead:'Aeron regierte mit unumschränkter Gewalt. Der Adel beugte sich, die Höfe schwiegen — doch der Frieden seiner Herrschaft war der Frieden der Furcht.'},
 konstitution:{title:'Der Konstitutionelle König',subtitle:'Eine Krone, geteilt mit den Ständen',lead:'Aeron gab Macht ab, um sie zu sichern. Räte, Städte und Adel teilten fortan die Last der Regierung — Valdoria wurde zum Vorbild geordneter Herrschaft.'},
 volk:{title:'Der König des Volkes',subtitle:'Geliebt von den Geringsten',lead:'Aeron stellte das Wohl der Vielen über die Gunst der Wenigen. In jeder Gasse Caerhavens kannte man den König, der ihre Not zu seiner machte.'},
 gelehrter:{title:'Der Gelehrtenkönig',subtitle:'Wissen als Krone',lead:'Aerons Hof wurde zum Leuchtturm der Gelehrsamkeit. Karten, Sterne und Geheimnisse ferner Länder häuften sich in den Archiven von Meerfalkenruh.'},
 dynastie:{title:'Die Ewige Dynastie',subtitle:'Das Haus Valedor gesichert',lead:'Aeron legte die Krone in feste Hände. Prinz Lucen bestieg den Thron eines geeinten Reiches, und die Linie der Valedor schien für Generationen gesichert.'},
 kaufmann:{title:'Der Kaufmannskönig',subtitle:'Gold als Zepter',lead:'Unter Aeron floss der Reichtum der Welt durch Valdorias Häfen. Handelsflotten und Banken machten die Krone reicher als jedes Schwert es vermocht hätte.'},
 friedens:{title:'Der Friedensfürst',subtitle:'Ein Reich in Eintracht',lead:'Aeron schloss Bündnisse, wo andere Kriege suchten. Am Ende seiner Tage lag ein seltener, tiefer Friede über den Sieben Häfen.'},
 empire:{title:'Der Herr der Neuen Welt',subtitle:'Valdorias Reich über den Horizont hinaus',lead:'Aerons Segel fanden Länder, von denen die Alten nur träumten. Kolonien und Karten trugen den Namen Valdorias in eine neue Zeit.'},
 niedergang:{title:'Das Zerfallene Reich',subtitle:'Eine Krone, die zu schwer wurde',lead:'Am Ende zerrann Aeron die Macht zwischen den Fingern. Aufstände, leere Kassen und schwindende Treue ließen von der Krone über den Meeren nur eine Sage zurück.'},
 ausgeglichen:{title:'Der Weise Regent',subtitle:'Eine maßvolle Herrschaft',lead:'Aeron suchte in allem das Gleichgewicht. Kein Ruhm der Eroberung, kein Glanz des Goldes — aber ein Reich, das in Ruhe an seinen Erben überging.'},
 heiler:{title:'Der Heilerkönig',subtitle:'Der die Seuche bezwang',lead:'Als das Graue Fieber das Reich heimsuchte, stellte Aeron sich ihm mit Wissen und Fürsorge. Die Heilkunst seiner Zeit wurde zu seinem größten Vermächtnis.'},
 befreier:{title:'Der König der freien Häfen',subtitle:'Ein Reich aus Partnern, nicht Untertanen',lead:'Aeron regierte nicht durch Zwang, sondern durch Bündnis. Von den Freien Inseln bis in den Norden band er Valdoria zu einem Reich der Zustimmung.'}
};
