function pickPrivateIncident(){state.privateIncidentHistory=state.privateIncidentHistory||[];let all=state.privateIncidentHistory,recent=all.slice(-10),eligible=PRIVATE_INCIDENTS.filter(i=>state.life.age>=i.min&&state.life.age<=i.max&&(!i.when||i.when(state))&&!(i.once&&all.includes(i.id))&&!recent.includes(i.id));if(!eligible.length)eligible=PRIVATE_INCIDENTS.filter(i=>state.life.age>=i.min&&state.life.age<=i.max&&(!i.when||i.when(state))&&!i.once&&!recent.includes(i.id));if(!eligible.length)return null;if((state.turn+state.life.age)%3===0&&state.turn>2)return null;return eligible[Math.abs(state.turn*11+state.year+state.decisions.length)%eligible.length].id}
