function choosePrivateIncident(code){let[id,choiceId]=code.split(':'),i=PRIVATE_INCIDENTS.find(x=>x.id===id),choice=i&&i.choices.find(c=>c.id===choiceId);if(!i||!choice||state.pendingPrivateIncident!==id)return;let snap=snapAll();choice.apply(state);state.privateIncidentHistory=state.privateIncidentHistory||[];state.privateIncidentHistory.push(id);state.privateIncidentHistory=state.privateIncidentHistory.slice(-40);state.pendingPrivateIncident=null;normalizeState();recordDecision(`Privater Zwischenfall · ${personalizeText(i.title)}`,`${personalizeText(choice.label)}. Dieser persönliche Moment bleibt Teil der Lebensgeschichte.`,{kind:'private'});persist();flashDeltas(snap);toast('Ein persönlicher Weg',personalizeText(choice.label));render()}
function makeEmergentContext(issue){let regions=Object.values(state.regions),region=state.regions[issue?.region]||regions.sort((a,b)=>(b.unrest-a.unrest)+(a.loyalty-b.loyalty)/5)[0];let target=issue?.target||Object.keys(state.relations).sort((a,b)=>state.relations[a]-state.relations[b])[0];return {region,target}}
function pickEmergentIssue(){let eligible=EMERGENT_TEMPLATES.filter(t=>!t.when||t.when(state)),recent=(state.emergentHistory||[]).slice(-8),pool=eligible.filter(t=>!recent.includes(t.id));if(!pool.length)pool=eligible;let t=pool[(state.turn+state.decisions.length+state.year)%pool.length],region=Object.entries(state.regions).sort((a,b)=>(b[1].unrest-a[1].unrest)+(a[1].loyalty-b[1].loyalty)/5)[0][0],target=Object.keys(state.relations).sort((a,b)=>state.relations[a]-state.relations[b])[0];return {id:t.id,region,target,serial:state.turn}}
function emergentPanel(){if(!state.emergent)return '';let t=EMERGENT_TEMPLATES.find(x=>x.id===state.emergent.id);if(!t)return '';let d=t.make(state,makeEmergentContext(state.emergent));return `<section class="storybeat emergent"><div class="sb-ornament">✦</div><div class="sb-body"><div class="sb-kicker">✦ OFFENE LAGE · AUS DEINER REGENTSCHAFT ENTSTANDEN</div><h2>${d.title}</h2><p>${d.text}</p><div class="sb-choices">${d.choices.map((c,i)=>`<button data-emergent="${t.id}:${i}"><b>${c.label}</b><span>${c.intent||decisionIntent(c.label,`${d.title} ${d.text}`)}</span></button>`).join('')}</div></div></section>`}
function chooseEmergent(code){let[id,idx]=code.split(':'),issue=state.emergent,t=EMERGENT_TEMPLATES.find(x=>x.id===id);if(!issue||issue.id!==id||!t)return;let d=t.make(state,makeEmergentContext(issue)),choice=d.choices[+idx];if(!choice)return;let snap=snapAll();choice.apply(state);state.emergentHistory.push(id);state.emergentHistory=state.emergentHistory.slice(-24);state.emergent=null;normalizeState();recordDecision(`${d.title} — ${choice.label}`,'Diese Wahl verändert die offene Simulation und schafft neue Gewinner, Gegner und spätere Lagen.');persist();flashDeltas(snap);toast('Euer eigener Weg',choice.label);render()}
function pickStoryBeat(){
 if(state.story.ended)return null;
 let elig=STORY.filter(b=>!state.story.seen.includes(b.id)&&state.story.threads[b.thread]===b.stage&&(!b.when||b.when(state)));
 if(!elig.length)return null;
 elig.sort((a,b)=>(state.story.threadTurn[a.thread]||0)-(state.story.threadTurn[b.thread]||0));
 return elig[0].id;
}
function chooseStory(code){let i=code.lastIndexOf(':'),id=code.slice(0,i),ci=+code.slice(i+1),b=STORY.find(x=>x.id===id);if(!b||state.story.beat!==id)return;let ch=b.choices[ci];if(!ch)return;let snap=snapAll();state.story._chain=null;ch.apply(state);state.story.seen.push(id);let chain=state.story._chain;state.story._chain=null;state.story.beat=(chain&&!state.story.seen.includes(chain)&&STORY.find(x=>x.id===chain))?chain:null;normalizeState();let th=THREADS[b.thread];recordDecision('Handlung — '+b.title,`${ch.label}. Die Entscheidung verändert den weiteren Verlauf dieses Konflikts.`);persist();flashDeltas(snap);toast(state.story.beat?'Die Folgen fordern eine weitere Wahl':'Die Geschichte wendet sich',`${th?th.name+': ':''}${ch.label}`);render()}
