 let axes=[['KRONMACHT',c.crown],['HANDELSFREIHEIT',c.coin],['GEMEINWOHL',c.commons]].map(([n,v])=>`<div class="path-axis"><span>${n}</span><div><i style="width:${Math.abs(v)/2}%;margin-left:${v<0?50-Math.abs(v)/2:50}%" class="${v<0?'left':''}"></i></div><b>${v>0?'+':''}${Math.round(v)}</b></div>`).join('');
