function romanNumeral(n){const m=[['X',10],['IX',9],['V',5],['IV',4],['I',1]];let r='';for(const[s,v]of m)while(n>=v){r+=s;n-=v}return r||'I'}
function showChapter(n){showModal('EIN NEUES KAPITEL',`<div class="chapter-card"><div class="chapter-numeral">${romanNumeral(n)}</div><div class="eyebrow">KAPITEL ${n}</div><h2>${chapterName(n)}</h2><p>Die Jahre ziehen ins Land, und mit ihnen wandelt sich das Reich. Neue Kräfte erheben sich, alte Fäden laufen zusammen.</p><button class="secondary-button close-modal-btn">WEITERREGIEREN</button></div>`);let btn=document.querySelector('.close-modal-btn');if(btn)btn.onclick=()=>$('#modal').close()}
function computeEnding(s){
 const o=s.story.outcomes,f=s.story.flags,c=s.course||{crown:0,coin:0,commons:0};
 const collapse=s.stats.legitimacy<25||s.stats.stability<22;
 let sc={
  seakaiser:s.stats.trade+s.stats.navy+(o.aurelia==='aur_alliance'?25:0)+(o.discovery==='dis_colonies'?25:0),
  eroberer:(o.nordhaven==='conquered'?70:0)+(o.nordhaven==='vassal'?35:0)+s.stats.army+(c.crown>25?15:0),
  tyrann:(c.crown>40?45:0)+(f.tyranny||0)*10+(f.ironhand?15:0)+(f.conqueror?10:0),
  konstitution:(c.crown<-25?45:0)+s.factions.cities*0.4+s.factions.nobles*0.3+(o.faith==='fai_reform'?15:0),
  volk:(c.commons>30?45:0)+s.factions.people*0.4+(f.benevolence||0)*8+(o.faith==='fai_reform'?15:0),
  gelehrter:s.stats.intelligence+(o.discovery==='dis_newlands'?25:0)+(f.shadow_web?15:0)+(s.relations.Lysara>50?10:0),
  dynastie:s.private.heir*0.6+(f.heir_crowned?40:0)+(o.dynasty==='dyn_strong'?30:0),
  kaufmann:s.stats.trade*0.7+s.factions.merchants*0.5+(f.merchant_prince?25:0)+(o.aurelia==='aur_tradewin'?20:0),
  friedens:(o.nordhaven==='allied'?35:0)+(o.aurelia==='aur_alliance'?20:0)+s.stats.stability*0.4+(f.benevolence||0)*5,
  empire:(f.empire||0)*20+(o.discovery==='dis_colonies'?30:0)+s.stats.navy*0.4,
  heiler:(o.plague==='cure'?55:0)+(o.plague==='contained'?20:0)+(f.benevolence||0)*7+(s.relations.Lysara>50?10:0),
  befreier:(o.isles==='federated'?35:0)+(o.nordhaven==='allied'?25:0)+(o.aurelia==='aur_alliance'?15:0)+(c.crown<-20?25:0)+(f.benevolence||0)*4
 };
 let key=collapse?'niedergang':Object.entries(sc).sort((a,b)=>b[1]-a[1])[0][0];
 const E=ENDINGS[key]||ENDINGS.ausgeglichen;
 let frags=Object.values(o).map(out=>THREAD_EPILOGUES[out]).filter(Boolean);
 let flavor=[];
 if((f.tyranny||0)>=3)flavor.push('Man nannte Aeron den Eisernen; seine Feinde flüsterten seinen Namen nur hinter vorgehaltener Hand.');
 if((f.benevolence||0)>=2)flavor.push('Das Volk sang Lieder über den König, der ihre Bürde zu seiner machte.');
 if(f.heir_crowned)flavor.push('Prinz Lucen bestieg den Thron eines gefestigten Reiches — das Haus Valedor würde dauern.');
 else if(o.dynasty==='dyn_rival')flavor.push('Um die Nachfolge aber sammelten sich bereits die Klingen rivalisierender Vettern.');
 if(f.empire)flavor.push('Auf Karten ferner Höfe trug ein neuer Kontinent nun valdorische Namen.');
 if(f.shadow_web)flavor.push('Kein Geheimnis der Höfe blieb der Krone verborgen; Aerons Augen reichten bis in fremde Schlafgemächer.');
 return {key,title:E.title,subtitle:E.subtitle,lead:E.lead,frags,flavor,stats:{legit:s.stats.legitimacy,stab:s.stats.stability,trade:s.stats.trade,army:s.stats.army,navy:s.stats.navy,reserve:s.reserve,year:s.year}};
}
