function showEpilogue(e){if(!e)return;let body=`<div class="epilogue"><div class="eyebrow">DAS VERMÄCHTNIS DER KRONE · ${e.stats.year}</div><h2>${personalizeText(e.title)}</h2><div class="epi-sub">${personalizeText(e.subtitle)}</div><p class="epi-lead">${personalizeText(e.lead)}</p>${e.frags.map(f=>`<p class="epi-frag">${personalizeText(f)}</p>`).join('')}${e.flavor.map(f=>`<p class="epi-flavor">${personalizeText(f)}</p>`).join('')}<div class="epi-stats">${[['LEGITIMITÄT',e.stats.legit],['STABILITÄT',e.stats.stab],['HANDEL',e.stats.trade],['HEER',e.stats.army],['FLOTTE',e.stats.navy]].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}<div><small>STAATSSCHATZ</small><b>${fmt(e.stats.reserve)} ₲</b></div></div><p class="epi-note">So spräche die Nachwelt, endete Eure Herrschaft in diesem Jahr. Doch die Regentschaft dauert an, solange Ihr es wünscht.</p><div class="epi-actions"><button class="secondary-button" id="continue-btn">WEITERREGIEREN</button><button class="secondary-button" id="restart-btn">NEUE REGENTSCHAFT BEGINNEN</button></div></div>`;showModal('CHRONIK DER KRONE',body);let cb=document.querySelector('#continue-btn');if(cb)cb.onclick=()=>$('#modal').close();let btn=document.querySelector('#restart-btn');if(btn)btn.onclick=()=>restartCampaign()}
