 for(const id of ['mother','regent','queen','heir','princess'])state.characterState[id]={trust:id==='mother'?state.private.mother||68:id==='princess'?state.private.princess||60:50,influence:id==='regent'?72:45,health:80,ambition:45,secrets:0,mood:'aufmerksam',history:[],lastActionTurn:0,...(state.characterState[id]||{})};
