function inferHistoryKind(title='',text='',meta={}){let raw=`${title} ${text}`.toLowerCase();if(meta.kind)return meta.kind;if(/krieg|angriff|heer|garnison|feldzug|frieden/.test(raw))return'war';if(/gold|handel|steuer|zoll|fonds|abgabe|markt/.test(raw))return'economy';if(/privat|famil|mutter|königin|kind|freund|hochzeit/.test(raw))return'private';if(/gesandt|bündnis|vertrag|diplomat|hof/.test(raw))return'diplomacy';if(/region|provinz|charta|straße|bau/.test(raw))return'region';return'realm'}
function memoryWeight(title='',text=''){let raw=`${title} ${text}`.toLowerCase();if(/versprech|eid|bündnis|charta|schutz/.test(raw))return{type:'Versprechen',weight:3};if(/verrat|embargo|handel.*eingestellt|krieg erklärt|geheim/.test(raw))return{type:'Bruch',weight:3};if(/hilfe|unterstütz|rett|begnad|milde/.test(raw))return{type:'Schuld',weight:2};if(/einverleib|hochzeit|frieden|vollendet/.test(raw))return{type:'Wendepunkt',weight:3};return{type:'Beschluss',weight:1}}
function rememberDecision(title,text,meta={}){ensureLivingHistoryState();let tone=memoryWeight(title,text),id=`m${state.turn}-${++state.memorySerial}`,entry={id,turn:state.turn,date:dateLabel(),title,text,kind:inferHistoryKind(title,text,meta),target:meta.target||null,region:meta.region||countryRegionId(meta.target)||state.selected||null,type:tone.type,weight:tone.weight,echoes:[]};state.memories.unshift(entry);state.memories=state.memories.slice(0,140);return entry}
function matchingMemory(kind,target,region,beforeTurn=Infinity){ensureLivingHistoryState();return state.memories.find(m=>m.turn<beforeTurn&&(target&&(m.target===target)||region&&m.region===region||m.kind===kind))||null}
function addHistoryEcho(memory,title,text,kind='realm'){if(!memory)return null;let echo={turn:state.turn,title,text,kind};memory.echoes=Array.isArray(memory.echoes)?memory.echoes:[];memory.echoes.unshift(echo);memory.echoes=memory.echoes.slice(0,8);return memory.id}
function tutorialPanel(view){ensureLivingHistoryState();let t=TUTORIAL_STEPS[view];if(!t||!state.tutorial.enabled||state.tutorial.seen.includes(view))return'';return `<aside class="guided-help"><div class="guided-number">?</div><div><small>KURZE ORIENTIERUNG</small><h3>${t.title}</h3><p>${t.text}</p></div><div class="guided-actions"><button data-tutorial-seen="${view}">VERSTANDEN</button><button data-tutorial-off>HILFEN AUS</button></div></aside>`}
function regionIdentityPanel(id,interactive=false){ensureLivingHistoryState();let identity=REGION_IDENTITIES[id],story=state.regionStories[id];if(!identity||!story)return'';let actions=interactive?`<div class="identity-actions"><button data-region-identity="${id}:tradition" ${story.lastActionTurn===state.turn?'disabled':''}>TRADITION EHREN<span>${identity.tradition}</span></button><button data-region-identity="${id}:reform" ${story.lastActionTurn===state.turn?'disabled':''}>BEHUTSAM REFORMIEREN<span>${identity.tension} neu ordnen</span></button><button data-region-identity="${id}:council" ${story.lastActionTurn===state.turn?'disabled':''}>ÖRTLICHEN RAT HÖREN<span>${identity.elite} einberufen</span></button></div>`:'';return `<section class="region-identity"><img src="${identity.image}" alt="Kultur und Landschaft von ${state.regions[id]?.name||id}"><div class="identity-copy"><div class="eyebrow">REGIONALE IDENTITÄT · ${story.policy.toUpperCase()}</div><h4>„${identity.motto}“</h4><p>${identity.identity}.</p><dl><div><dt>ÖRTLICHE MACHT</dt><dd>${identity.elite}</dd></div><div><dt>HOFFNUNG</dt><dd>${identity.aspiration}</dd></div><div><dt>SPANNUNG</dt><dd>${identity.tension}</dd></div></dl>${actions}</div></section>`}
function regionIdentityAction(code){let[id,act]=code.split(':'),r=state.regions[id],story=ensureLivingHistoryState().regionStories[id],identity=REGION_IDENTITIES[id];if(!r||!story||!identity||story.lastActionTurn===state.turn)return;let cost=act==='tradition'?500000:act==='reform'?900000:250000;if(state.reserve<cost)return toast('Schatzkammer',`Für diese regionale Maßnahme fehlen ${fmt(cost)} Gold.`);state.reserve-=cost;story.lastActionTurn=state.turn;let text='';if(act==='tradition'){story.policy='traditionsnah';story.favor+=8;story.tension-=4;r.loyalty+=4;text=`Die Krone nimmt an „${identity.tradition}“ teil und bestätigt damit sichtbar die Würde der Region.`}else if(act==='reform'){story.policy='reformorientiert';story.favor-=2;story.tension+=5;r.infrastructure+=4;r.wealth+=3;text=`Königliche Fachleute ordnen ${identity.tension.toLowerCase()} neu, ohne die örtlichen Institutionen ganz zu verdrängen.`}else{story.policy='örtlich beraten';story.favor+=5;story.tension-=2;r.unrest-=3;state.stats.intelligence+=1;text=`Der ${identity.elite} wird gehört; seine Beschwerden und Vorschläge werden Teil der königlichen Verwaltung.`}recordDecision(`Regionallinie · ${r.name}`,text,{kind:'region',region:id,target:COUNTRY_META[id]?.key});normalizeState();persist();render();toast(r.name,text)}
function visibleCharacterIds(){let ids=['mother','princess','regent'];if(state.life.spouse)ids.push('queen');if(state.life.children.length)ids.push('heir');return ids}
function characterDisplay(id){let roster=familyRoster(),f=roster.find(x=>x.id===id),n=ensureCastNames();if(f)return{name:f.name,image:f.image||'assets/portrait-queen-elara.webp',role:f.role};if(id==='regent')return{name:advisorDisplayName(0),image:'assets/portrait-mara-veyne.webp',role:'Kanzler der Regentschaft'};return{name:n.king,image:'assets/portrait-king-aeron.webp',role:'Haus Valedor'}}
function characterDynamicsPanel(){ensureLivingHistoryState();let cards=visibleCharacterIds().map(id=>{let c=state.characterState[id],d=characterDisplay(id),a=CHARACTER_AMBITIONS[id]||CHARACTER_AMBITIONS.regent,used=c.lastActionTurn===state.turn;return `<article class="living-character"><img src="${d.image}" alt="${d.name}"><div class="living-character-copy"><small>${d.role}</small><h3>${d.name}</h3><p><b>Eigener Wunsch:</b> ${a.title}.</p><p><b>Unausgesprochene Furcht:</b> ${a.fear}.</p><div class="character-signals"><span>${c.mood}</span><span>Einfluss ${Math.round(c.influence)}</span><span>${c.secrets?'verborgene Absichten':'offenes Verhältnis'}</span></div><div class="character-actions"><button data-character-policy="${id}:listen" ${used?'disabled':''}>VERTRAULICH ZUHÖREN</button><button data-character-policy="${id}:honor" ${used?'disabled':''}>ÖFFENTLICH EHREN</button><button data-character-policy="${id}:watch" ${used?'disabled':''}>DISKRET BEOBACHTEN</button></div></div></article>`}).join('');return panel('MENSCHEN MIT EIGENEM WILLEN','Nähe, Ehrgeiz und Geheimnisse entwickeln sich weiter',`<div class="living-characters">${cards}</div>`)}
function characterPolicy(code){let[id,act]=code.split(':'),c=ensureLivingHistoryState().characterState[id],d=characterDisplay(id);if(!c||c.lastActionTurn===state.turn||state.private.actionPoints<1)return;state.private.actionPoints--;c.lastActionTurn=state.turn;let text='';if(act==='listen'){c.trust+=8;c.ambition-=2;c.mood='gehört';state.private.stress-=2;text=`Ihr hört ${d.name} ohne Zeugen zu. Nicht jedes Wort ist Rat; manches ist Angst, die nun nicht länger unbemerkt bleibt.`}else if(act==='honor'){c.trust+=5;c.influence+=7;c.ambition+=3;c.mood='bestärkt';state.stats.legitimacy+=1;text=`${d.name} erhält vor dem Hof einen sichtbaren Platz an Eurer Seite. Das schafft Bindung, aber auch eigene Macht.`}else{c.secrets=Math.max(0,c.secrets-1);state.stats.intelligence+=2;c.trust-=4;c.mood='beobachtet';text=`Vertraute der Krone beobachten ${d.name}. Ihr erfahrt mehr, doch die neue Kälte bleibt nicht völlig verborgen.`}c.history.unshift({turn:state.turn,act,text});recordDecision(`Privat: ${d.name}`,text,{kind:'private',target:id});normalizeState();persist();render();toast(d.name,text)}
function livingHistoryYearTick(){ensureLivingHistoryState();let yearChanged=state.season===0;if(!yearChanged)return;let ids=visibleCharacterIds(),idx=(state.year+state.nameSeed)%ids.length,id=ids[idx],c=state.characterState[id],d=characterDisplay(id);c.ambition=clamp(c.ambition+(c.influence>60?3:1),0,100);c.health=clamp(c.health+(state.private.stress>70?-2:1),20,100);let characterMemory=matchingMemory('private',id,null,state.turn),characterText=c.trust<42?`${d.name} zieht sich aus Eurer Nähe zurück und sucht eigene Verbündete am Hof.`:c.ambition>68?`${d.name} beginnt, einen lange gehegten Wunsch durch ein eigenes Netz am Hof voranzutreiben.`:`${d.name} greift eine frühere vertrauliche Bitte auf und hilft, einen Konflikt im Haus Valedor zu glätten.`;c.mood=c.trust<42?'distanziert':c.ambition>68?'zielstrebig':'verbunden';state.events.unshift({turn:state.turn,date:dateLabel(),title:`Eigenes Leben: ${d.name}`,text:characterText,kind:'private',causeId:addHistoryEcho(characterMemory,`Eigenes Leben: ${d.name}`,characterText,'private')});
 let owned=Object.keys(state.regions).filter(r=>!COUNTRY_META[r]||isAnnexed(r)),rid=owned[(state.year+Math.floor(state.nameSeed/7))%owned.length],rs=state.regionStories[rid],region=state.regions[rid],identity=REGION_IDENTITIES[rid];if(region&&identity&&state.turn-rs.lastEventTurn>=4){rs.lastEventTurn=state.turn;let cause=matchingMemory('region',COUNTRY_META[rid]?.key,rid,state.turn),good=rs.favor>=rs.tension,txt=good?`${identity.elite} erinnert öffentlich an die Achtung, welche die Krone der Region erwiesen hat. ${identity.aspiration} erscheint vielen nun erreichbar.`:`Der alte Streit „${identity.tension}“ bricht erneut auf. Die Menschen messen aktuelle Befehle an früheren Zusagen der Krone.`;region.loyalty+=good?2:-2;region.unrest+=good?-1:3;state.events.unshift({turn:state.turn,date:dateLabel(),title:`Stimme aus ${region.name}`,text:txt,kind:'region',region:rid,causeId:addHistoryEcho(cause,`Stimme aus ${region.name}`,txt,'region')})}}
function peaceTermAvailable(name,id,term){let w=warSnapshot(name),p=PEACE_TERMS[term];if(!p)return false;if(term==='annex')return!!w.pol.occupied;return w.progress>=p.need}
function openPeaceConference(id){let m=COUNTRY_META[id],r=state.regions[id];if(!m||!r||!state.diplo?.[m.key]?.war)return toast('Kein Kriegszustand','Eine Friedenskonferenz ist nur während eines Krieges möglich.');let w=warSnapshot(m.key),terms=Object.entries(PEACE_TERMS).map(([key,t])=>{let ok=peaceTermAvailable(m.key,id,key);return `<button data-peace-term="${id}:${key}" ${ok?'':'disabled'}><small>${t.stance.toUpperCase()} · BENÖTIGT ${t.need}% KRIEGSFORTSCHRITT</small><b>${t.label}</b><span>${t.summary}</span><em>${ok?'ALS VERTRAGSZIEL WÄHLEN':'NOCH NICHT DURCHSETZBAR'}</em></button>`}).join('');showModal(`FRIEDENSKONFERENZ · ${m.key}`,`<div class="peace-conference"><div class="peace-balance"><div><small>VALDORISCHE VERHANDLUNGSMACHT</small><b>${w.progress}%</b><span>${w.outlook}</span></div><div><small>GEMELDETE FEINDSTÄRKE</small><b>${enemyStrengthLabel(id,w.enemy)}</b><span>${w.pol.occupied?'Regierung und Hauptstadt sind besetzt':w.front}</span></div></div><p>Der Krieg endet erst, wenn Ihr ein Vertragsziel bestätigt. Was Ihr verlangt, bestimmt die Nachkriegsordnung und bleibt in der Erinnerung beider Reiche.</p><div class="peace-terms">${terms}</div></div>`);document.querySelectorAll('[data-peace-term]').forEach(b=>b.onclick=()=>settlePeace(...b.dataset.peaceTerm.split(':')))}
function settlePeace(id,term){let m=COUNTRY_META[id],r=state.regions[id],d=m&&state.diplo?.[m.key],t=PEACE_TERMS[term];if(!m||!r||!d?.war||!t||!peaceTermAvailable(m.key,id,term))return;let snap=snapAll(),w=warSnapshot(m.key),text='';if(term==='annex'){let result=annexTerritory(id,'der Friedenskonferenz',false);text=result.text}else{d.war=false;d.campaign={...(d.campaign||{}),endedTurn:state.turn,lastOutcome:`Der Vertrag „${t.label}“ beendet den Krieg.`};if(term==='statusquo'){state.relations[m.key]+=10;state.stats.stability+=3;text=`Beide Höfe verzichten auf weitere Forderungen. Gefangene kehren heim und die Grenze bleibt unverändert.`}if(term==='reparations'){state.reserve+=4000000;state.relations[m.key]-=8;r.wealth-=4;text=`${m.key} verpflichtet sich zu Entschädigungen für den valdorischen Wiederaufbau. Der Frieden ist echt, aber bitter.`}if(term==='trade'){d.treaty='trade';state.stats.trade+=4;state.relations[m.key]+=3;text=`Valdorische Kaufleute erhalten bevorzugte Häfen und Zölle. Aus dem Krieg entsteht eine wirtschaftliche Abhängigkeit.`}if(term==='demilitarize'){r.garrison=Math.max(8,r.garrison-18);state.relations[m.key]-=10;text=`Grenzfestungen werden geschleift und Teile des feindlichen Heeres entlassen. Der Nachbar fühlt sich gedemütigt, Valdoria aber sicherer.`}if(term==='vassal'){let p=state.countryPolicy[m.key]||(state.countryPolicy[m.key]={});p.vassal=true;p.tribute=1800000;d.treaty='vassal';state.relations[m.key]-=5;text=`Der Hof von ${m.key} bleibt bestehen, schwört Valdoria jedoch Schutztreue und entrichtet künftig Tribut.`}}state.peaceHistory.unshift({turn:state.turn,country:m.key,term,title:t.label,progress:w.progress,text});recordDecision(`Friedensvertrag · ${m.key}`,text,{kind:'war',target:m.key,region:id});normalizeState();persist();$('#modal').close();render();flashDeltas(snap);toast('Der Krieg ist beendet',text)}
ensureLivingHistoryState();
