function projectScene(id,pct){
 const done=pct>=1,R=t=>pct>=t?1:0.5,win=done?'#ffd77a':'#3c4a51';
 const bg=`<defs><linearGradient id="sky-${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#162a34"/><stop offset=".5" stop-color="#294049"/><stop offset=".8" stop-color="#6f6146"/><stop offset="1" stop-color="#b6884f"/></linearGradient><linearGradient id="sea-${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2a555f"/><stop offset="1" stop-color="#163942"/></linearGradient></defs><rect width="320" height="180" fill="url(#sky-${id})"/><circle cx="252" cy="42" r="19" fill="#f3d999" opacity=".9"/><circle cx="252" cy="42" r="31" fill="#f3d999" opacity=".1"/><g class="bx-cloud"><ellipse cx="70" cy="40" rx="34" ry="8" fill="#cdd6cf" opacity=".16"/><ellipse cx="94" cy="36" rx="20" ry="7" fill="#cdd6cf" opacity=".12"/></g><rect y="150" width="320" height="30" fill="url(#sea-${id})"/><path class="bx-wave" d="M0 159 Q80 153 160 159 T320 159" fill="none" stroke="#6f9a9c" stroke-width="1.3" opacity=".5"/><path class="bx-wave2" d="M0 167 Q80 162 160 167 T320 167" fill="none" stroke="#5a888c" stroke-width="1.1" opacity=".36"/>`;
 const glow=done?`<ellipse class="bx-glow" cx="160" cy="128" rx="130" ry="46" fill="#ffcf6e" opacity=".16"/>`:'';
 const body=(PROJECT_SCENES[id]||PROJECT_SCENES.palace)(R,win,done);
 const crane=(pct>0&&pct<1)?`<g class="bx-crane"><rect x="250" y="72" width="4" height="78" fill="#6e5a37"/><rect x="228" y="72" width="46" height="4" fill="#6e5a37"/><line x1="234" y1="74" x2="234" y2="104" stroke="#3a3122" stroke-width="1.5"/><rect x="230" y="104" width="9" height="7" fill="none" stroke="#3a3122" stroke-width="1.5"/></g>`:'';
 const fp=PROJECT_FLAG[id]||[160,60];
 const flag=done?`<g class="bx-flag" transform="translate(${fp[0]},${fp[1]})"><rect x="0" y="-4" width="2.5" height="22" fill="#7a6743"/><path d="M2.5 -4 L20 1 L2.5 6 Z" fill="#9d241b"/></g>`:'';
 return `<svg viewBox="0 0 320 180" class="build-scene" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${bg}${glow}${body}${crane}${flag}</svg>`;
}
function projectVisual(id,progress,total,large=false){let pct=total?Math.max(0,Math.min(1,progress/total)):(progress>=1?1:0),p=PROJECTS.find(x=>x.id===id),value=Math.round(pct*100);return `<div class="construction-visual project-painted ${large?'large':''} ${pct===0?'planned':''} ${pct>=1?'finished':''}" data-building="${id}" style="--build:${value}%"><img src="${PROJECT_ART[id]}" alt="${p?.name||'Königliches Bauwerk'}" loading="lazy"><div class="project-reveal"></div><div class="project-art-status"><span>${pct>=1?'VOLLENDET':pct>0?'BAUPHASE '+value+'%':'ENTWURF'}</span><i><b style="width:${value}%"></b></i></div></div>`}
function projectsView(){
 let active=state.projects.map(p=>{let d=PROJECTS.find(x=>x.id===p.id),turns=p.turns||d.turns,pct=Math.round(p.progress/turns*100);return `<article class="construction-card">${projectVisual(p.id,p.progress,turns,true)}<div class="construction-copy"><span class="tag">IM BAU · PHASE ${Math.min(p.progress+1,turns)} VON ${turns}</span><h3>${d.name}</h3><p>${p.region?`${state.regions[p.region].name} · ${PROJECT_DESIGNS[p.design||'balanced'].label} · ${PROJECT_CONTRACTORS[p.contractor||'guild'].label}.`:'Während des Baus entstehen Arbeitsplätze, Materialbedarf und neue Erwartungen.'}</p><div class="progress"><i style="width:${pct}%"></i></div><small>${pct}% vollendet · Qualität ${p.quality??50}% · ${p.stalls||0} Verzögerungen</small></div></article>`}).join('');
 let catalogue=PROJECTS.map(p=>{let building=state.projects.some(x=>x.id===p.id),done=state.completedProjects.includes(p.id),disabled=building||done||Math.max(state.reserve,state.buildingFund)<p.cost*.82;return `<div class="action-card project-option ${done?'completed':''}">${projectVisual(p.id,done?1:0,1)}<span class="tag">${done?'VOLLENDET':p.type}</span><h3>${p.name}</h3><p>${decisionIntent(p.name,p.type)} Standort, Entwurf und Auftragnehmer bestimmen die tatsächliche Bauzeit.</p><div class="cost">BASISKOSTEN · ${fmt(p.cost)} ₲</div><button data-project="${p.id}" ${disabled?'disabled':''}>${done?'VOLLENDET':building?'BEREITS IM BAU':'BAUPLAN ERSTELLEN'}</button></div>`}).join('');
 return pageTitle('WERKE FÜR DIE EWIGKEIT','Bauprojekte','Jede Baustelle wächst sichtbar und verändert ihre Region schon vor der Vollendung.')+(active?panel('BAUSTELLEN DES REICHES',`${state.projects.length} aktiv`,`<div class="construction-list">${active}</div>`):'')+`<div class="cards" style="margin-top:18px">${catalogue}</div>`
}
